UPDATE doctors SET
  description = 'Врач травматолог-ортопед высшей категории в Новосибирске со стажем более 20 лет, специализирующийся на диагностике и лечении заболеваний и травм опорно-двигательного аппарата: артроза, артрита, бурсита, тендинита, боли в коленном, тазобедренном и плечевом суставах, боли в спине и позвоночнике. Окончил Воронежскую государственную медицинскую академию им. Н.Н. Бурденко в 2006 г. по специальности «Лечебное дело». Окончил больничную интернатуру по специальности «травматология и ортопедия» в 2007 г. Окончил ординатуру по специальности «травматология и ортопедия» в 2014 г. в НИИТО им. Я.Л. Цивьяна. На протяжении 12 лет занимался хирургическим лечением травм и заболеваний опорно-двигательного аппарата. На протяжении более чем 8 лет занимается консервативным безоперационным лечением опорно-двигательного аппарата, используя современные методы лечения, активно применяет регенераторные методики. При лечении опорно-двигательного аппарата использует медикаментозное лечение, медикаментозные блокады (внутрисуставные блокады, параартикулярные блокады, внутрикостные блокады), внутрисуставные введения протезов внутрисуставной жидкости (гиалуроновая кислота), коллагенотерапию, активно применяет PRP-терапию (плазмотерапию) и SVF-терапию собственными клетками жировой ткани. Также врач является специалистом по ортезированию — подбор бандажей, ортезов, корсетов и стелек. На своём приёме врач собирает жалобы и краткий анамнез, проводит ортопедический осмотр, назначает необходимые обследования (УЗИ суставов, рентген, МРТ), ставит диагноз и составляет индивидуальный план лечения согласно выявленной патологии, осуществляет медицинское сопровождение пациента до полного восстановления.',
  experience = 'Травматология · Ортопедия · Высшая категория · PRP и SVF-терапия · Внутрикостные блокады · Ортезирование · Стаж 20+ лет'
WHERE name = 'Палий Василий Николаевич';
